/**
 * How Palm-leaf fan (`shuro-uchiwa`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/shuro-uchiwa";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Pleated palm blades spread in pairs around the upright one. Each blade has a rounded tip, a white midrib and three V-shaped pleats. The handle has two small scrolls.","ja":"中央の一枚を真上に置き、折り目のある棕櫚の葉を左右に広げます。葉先を丸くし、白い中肋と三つのV字の折り目を入れます。柄には小さな巻きを二つ置きます。"};

export default construction;
export { construction, description };
